solution.css:
/* Photo gallery · style.css */

/* Step 5: reset and base typography */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: Arial, sans-serif;
  background-color: #f7f5fb;
  color: #1e1527;
}

header,
main,
footer {
  max-width: 960px;
  margin: 0 auto;
  padding: 16px 24px;
}

h1 {
  margin-top: 8px;
  color: #43235f;
}

footer {
  color: #5c5368;
  font-size: 14px;
}

/* Step 6: the gallery grid */
.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.photo img {
  display: block;
  width: 100%;
}

/* Step 7: filter buttons and the active one */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}

.filter-btn {
  padding: 8px 16px;
  border: 1px solid #cfc8d8;
  border-radius: 999px;
  background-color: #ffffff;
  color: #1e1527;
  font-size: 15px;
  font-weight: bold;
  cursor: pointer;
}

.filter-btn.active {
  background-color: #602b7a;
  border-color: #602b7a;
  color: #ffffff;
}

/* Step 8: the overlay with the title, darker on hover */
.photo {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
}

.overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: flex-end;
  padding: 12px;
  color: #ffffff;
  background-color: rgba(30, 21, 39, 0);
  transition: background-color 0.4s;
}

.overlay h2 {
  font-size: 18px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
}

.photo:hover .overlay {
  align-items: center;
  justify-content: center;
  background-color: rgba(30, 21, 39, 0.7);
}

/* Step 9: 1 column on small screens */
@media (max-width: 600px) {
  .gallery {
    grid-template-columns: 1fr;
  }
}

/* Step 12: JavaScript adds the class "hidden" to the photos it hides */
.hidden {
  display: none;
}

solution.js:
// Photo gallery · script.js

// Step 10: select the filter buttons and the photos
const buttons = document.querySelectorAll(".filter-btn");
const photos = document.querySelectorAll(".photo");
console.log(buttons.length, photos.length);

// Step 11: listen to clicks on every button
buttons.forEach((btn) => {
  btn.addEventListener("click", () => {
    console.log(btn.dataset.filter);

    // Step 12: show the photos of that category and hide the rest
    const filter = btn.dataset.filter;
    photos.forEach((photo) => {
      if (filter === "all" || photo.dataset.category === filter) {
        photo.classList.remove("hidden");
      } else {
        photo.classList.add("hidden");
      }
    });

    // Step 13: highlight only the clicked button
    buttons.forEach((b) => {
      b.classList.remove("active");
    });
    btn.classList.add("active");
  });
});
